import{_ as i,o as a,c as s,a3 as t,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/import-export-statistik/nrw-export-ban-portal-markieren.png",o="/bilder/import-export-statistik/nrw-export-export-ban.png",d="/bilder/import-export-statistik/nrw-export-export-ban-datei.png",A=JSON.parse('{"title":"Schülerdaten für das BAN-Portal vorbereiten und exportieren","description":"","frontmatter":{"title":"Schülerdaten für das BAN-Portal vorbereiten und exportieren","source_pageid":1421,"source_revision":6993},"headers":[],"relativePath":"schild3/import-export-statistik/export-fuer-ban-portal-verwaltung-export.md","filePath":"schild3/import-export-statistik/export-fuer-ban-portal-verwaltung-export.md"}'),u={name:"schild3/import-export-statistik/export-fuer-ban-portal-verwaltung-export.md"};function h(c,n,p,m,g,b){return a(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="schulerdaten-fur-das-ban-portal-vorbereiten-und-exportieren" tabindex="-1">Schülerdaten für das BAN-Portal vorbereiten und exportieren <a class="header-anchor" href="#schulerdaten-fur-das-ban-portal-vorbereiten-und-exportieren" aria-label="Permalink to &quot;Schülerdaten für das BAN-Portal vorbereiten und exportieren&quot;">​</a></h1><p>Markieren Sie die zu meldenden Schülerinnen und Schüler und prüfen Sie ihre Angaben zur Anschlussperspektive. Danach erstellen Sie den Export für das BAN-Portal.</p><p>Zu KAoA gehört das <em>Belegungs-, Abrechnungs- und Nachweisportal</em>, das <a href="https://banportal-kaoa.de" target="_blank" rel="noreferrer"><em>BAN-Portal</em></a>. Nehmen Sie hier auch die <a href="https://banportal-kaoa.de/Home/About" target="_blank" rel="noreferrer">Information zum Portal und zum Supportkontakt</a> zur Kenntnis.</p><p>Hierbei sollen die Schüler identifiziert werden, die über keine konkrete Anschlussperspektive wie eine Ausbildung, Schulplatz, ein freiwilliges Jahr, Praktikum für den FHR und so weiter verfügen. Aus SchILD-NRW lassen sich die im Portal einzulesenden Daten exportieren. In der Regel sollte dies nur wenige Schüler betreffen.</p><h2 id="schuler-vorbereiten" tabindex="-1">Schüler vorbereiten <a class="header-anchor" href="#schuler-vorbereiten" aria-label="Permalink to &quot;Schüler vorbereiten&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/nrw-export-ban-portal-markieren.png"><img src="'+l+'" alt="Markieren Sie Schüler als für das BAN-Portal zu exportieren." loading="lazy"></a></p><p><em>Markieren Sie Schüler als für das BAN-Portal zu exportieren.</em></p><p>Damit Schülerdaten exportiert werden, müssen die Schüler als zu exportieren markiert werden.<br> Dies nehmen Sie für individuelle Schüler unter <em>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</em> mit dem gesetzten Haken bei <strong>Für Meldung an BAN-Portal</strong> vor.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Hinweis 1: Tragen Sie bei den Schülern vor dem Export unbedingt den (vorläufigen) Abschluss ein."),e("p",null,[r("Hinweis 2: Beachten Sie hierbei, dass die Markierung für den jeweils gewählten "),e("strong",null,"Lernabschnitt"),r(" gilt. In der Regel betrifft der BAN-Export nur den Abschluss-Lernabschnitt.")])],-1),t('<p><strong>Den Haken per Gruppenprozess setzen</strong></p><p>Für größere Gruppen lassen sich die Markierungen bei Bedarf komfortabel über einen <em>Gruppenprozess</em> setzen.</p><p>Wählen Sie zuerst die Schülergruppe aus, für welche die BAN-Markierungen gesetzt werden sollen und starten Sie den Gruppenprozess <em>Individualdaten ändern ➜ Lernabschitte</em>.</p><h2 id="ban-export" tabindex="-1">BAN-Export <a class="header-anchor" href="#ban-export" aria-label="Permalink to &quot;BAN-Export&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/nrw-export-export-ban.png"><img src="'+o+'" alt="Exportieren Sie die Datei für das BAN-Portal aus SchILD-NRW." loading="lazy"></a></p><p><em>Exportieren Sie die Datei für das BAN-Portal aus SchILD-NRW.</em></p><p>In der Regel muss beim Export keine Schülergruppe ausgewählt werden, da die zu exportierenden Schüler schon im aktuellen Lernabschnitt markiert sind. Nicht-markierte Schüler werden daher beim Export ignoriert.</p><p>Sie können für den BAN-Export ausgehend von der gesamten Schülermenge arbeiten.</p><p>Sollten Sie nur ausgewählte Schülermengen exportieren wollen, wählen Sie diese wie beim beim Gruppenprozess oben zuvor aus.</p><p>Im Anschluss gehen Sie über <em>Verwaltung ➜ Exporte</em> ➜ <strong>Export für BAN-Portal</strong>.</p><p><a href="/bilder/import-export-statistik/nrw-export-export-ban-datei.png"><img src="'+d+'" alt="Wählen Sie den Speicherort der Exportdatei. Der Dateiname BAN-Export.csv wird beibehalten." loading="lazy"></a></p><p><em>Wählen Sie den Speicherort der Exportdatei. Der Dateiname BAN-Export.csv wird beibehalten.</em></p><p>Im folgenden Fenster ist der <strong>Speicherort</strong> für die Datei zu wählen.</p><p>Hier im Beispiel wird im <em>SVWS-Arbeitsverzeichnis</em> der Unterordner <em>Export</em> ausgewählt.</p><p>Der Standard-Dateiname wird beibehalten.</p><p>Ebenso lässt sich hier der <strong>Lernabschnitt</strong> anwählen, für den der Export ausgeführt wird. Alle Schüler, die im betreffenden Lernabschnitt als <em>zu exportieren</em> markiert sind, werden nun berücksichtigt.</p><p>Klicken Sie auf <code>Exportieren</code>.</p><p>Der Export ist abgeschlossen. Die erzeugte Datei kann nun im BAN-Portal eingelesen werden.</p>',18),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,[r("Der Name "),e("code",null,"BAN-Export.csv"),r(" enthält keinen Lernabschnitt und bleibt von Jahr zu Jahr gleich. Wählen Sie beim Hochladen ins BAN-Portal deshalb ausdrücklich die gerade neu exportierte Datei.")])],-1),t(`<h2 id="bedeutung-der-tabellenwerte" tabindex="-1">Bedeutung der Tabellenwerte <a class="header-anchor" href="#bedeutung-der-tabellenwerte" aria-label="Permalink to &quot;Bedeutung der Tabellenwerte&quot;">​</a></h2><p>Sie erhalten eine Datei, in der spaltenweise die folgenden Daten enthalten sind:</p><pre><code> Name, Vorname, Geburtsdatum, Geschlecht, Wohnort, PLZ, Straße, Hausnummer, voraussichtlich erreichter Abschluss
</code></pre><p>Hierbei können im Feld <strong>Geschlecht</strong> diese Werte auftreten:</p><ul><li>m - <em>männlich</em></li><li>w - <em>weiblich</em></li><li>o - <em>ohne Angabe</em></li><li>d - <em>divers</em></li></ul><p>Ausschließlich bei Berufskollegs wird im Feld <strong>Gliederung</strong> der ASD-Schlüssel für die Schulgliederung ausgewiesen, aus dem jeweils die Bezeichnung des Bildungsganges abgeleitet werden kann</p><table tabindex="0"><thead><tr><th>Schulgliederung <br> (Schlüssel)</th><th>Bezeichnung des Bildungsganges</th></tr></thead><tbody><tr><td>A12</td><td>Ausbildungsvorbereitung in Vollzeitform gemäß §§ 18, 22 Absatz 3 APOBK Anlage A (Anlage A 2.2)</td></tr><tr><td>A17</td><td>Ausbildungsvorbereitung in Vollzeitform (Internationale Förderklasse) gemäß §§ 18, 22 Absatz 3 APOBK Anlage A (Anlage A 2.2)</td></tr><tr><td>B06</td><td>Berufsfachschule gemäß § 2 Nummer 1 APO-BK Anlage B (Anlage B 1)</td></tr><tr><td>B07</td><td>Berufsfachschule gemäß § 2 Nummer 2 APO-BK Anlage B (Anlage B 2)</td></tr><tr><td>C03</td><td>Berufsfachschule gemäß § 2 Nummer 3 Anlage C APO-BK (Anlage C 2)</td></tr><tr><td>C05</td><td>Fachoberschule gemäß § 8 Nummer 1 APO-BK Anlage C (Anlage C 3); Klasse 11</td></tr><tr><td>C06</td><td>Fachoberschule gemäß § 8 Nummer 1 APO-BK Anlage C (Anlage C 3); Klasse 12S</td></tr><tr><td>D02</td><td>Berufliches Gymnasium § 1a Absatz 1 Nummer 1 APO-BK Anlage D (Anlagen D 14-D 28)</td></tr></tbody></table><p>Im Feld <strong>voraussichtlich erreichter Abschluss</strong> finden sich die Buchstabenkürzel, die nach der Statistik den Abschluss angeben. Diese Spalte dient lediglich zu Informationszwecken für die Schulen und kann in der Exportdatei leer bleiben, da der Eintrag zum voraussichtlichen Abschluss automatisiert beim Import auf dem BAN-Portal ergänzt wird.</p><ul><li>A - <em>Ohne Abschluss</em></li><li>B - <em>Erster Schulabschluss (ohne Berechtigung zum Besuch der Klasse 10, Typ B)</em></li><li>C - <em>Erster Schulabschluss (mit Berechtigung zum Besuch der Klasse 10, Typ B)</em></li><li>D - <em>Erweiterter Erster Schulabschluss</em></li><li>F - <em>Mittlerer Schulabschluss - Fachoberschulreife ohne Berechtigung zum Besuch der gymnasialen Oberstufe</em></li><li>G - <em>Mittlerer Schulabschluss – Fachoberschulreife mit Berechtigung zum Besuch der gymnasialen Oberstufe (Einführungsphase)</em></li><li>H - <em>Fachhochschulreife (schulischer Teil)</em></li><li>I - <em>Mittlerer Schulabschluss – Fachoberschulreife mit Berechtigung zum Besuch der Qualifikationsphase 1</em></li><li>V - <em>Abschluss des zieldifferenten Bildungsgangs Lernen</em></li><li>M - <em>Abschlusszeugnis im zieldifferenten Bildungsgang Geistige Entwicklung</em></li><li>O - <em>Erster Schulabschluss nach Klasse 9 (mit Berechtigung zum Besuch der gymnasialen Oberstufe; § 43 Abs. 3 i.V.m. § 40 Abs. 4 S. 2 APO-SI)</em></li><li>U - <em>Erweiterter Erster Schulabschluss (mit Berechtigung zum Besuch der gymnasialen Oberstufe; § 41 Abs. 2 APO-SI i.V.m. § 40 Abs. 2 APO-GOSt)</em></li></ul><p>Felder ohne Eintrag werden als <em>A - Ohne Abschluss</em> gewertet.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Export_f%C3%BCr_BAN-Portal_(Verwaltung_Export)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6993.</p>`,12)])])}const S=i(u,[["render",h]]);export{A as __pageData,S as default};
